const body = $('TrustBox Webhook').item.json.body || {};
const incident = body.incident || {};
const merchant = body.merchant || {};
return [{
  json: {
    dossierId: 'DOSSIER-' + Date.now().toString().slice(-6),
    evidenceStandard: 'Section 65B Indian Evidence Act',
    auditStatus: 'IMMUTABLE_HASH_RECORDED',
    timestamp: new Date().toISOString(),
    merchantId: merchant.id || 'M12345678',
    orderId: incident.orderId || 'UNVERIFIED',
    fraudScore: incident.fraudScore || 1.0,
    forensicHash: 'SHA256:' + Math.random().toString(36).substring(2) + Date.now().toString(36)
  }
}];

