else if (userText.includes('help') || userText.includes('hi') || userText.includes('hello') || rawText.includes('नमस्ते') || rawText.includes('मदद') || rawText.includes('ನಮಸ್ಕಾರ') || rawText.includes('ಸಹಾಯ')) {
